      .catch(error => console.error('Network error:', error));
  } catch (error) {
    alert("There was an issue with the network. Please try again later.");
    return false;
  }

  return true;
}

function validateEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  return emailRegex.test(email);
