const axios = require('axios');
const retry = require('retry');

// Configuration
const apiEndpoint = 'https://api.example.com/products';
const expectedResponseStructure = {
  products: [
    { id: '', name: '', price: '' }
  ]
};
const maxAttempts = 3;

async function fetchData() {
  let attempts = 0;
  const retryOptions = {
    retries: maxAttempts,
    minTimeout: 1000, // Initial delay
    factor: 2,         // Exponential backoff multiplier
    maxTimeout: 60000   // Maximum timeout (in ms)
  };

  while (attempts < maxAttempts) {
    try {
      const response = await axios.get(apiEndpoint);
      if (!response.data || !Array.isArray(response.data.products)) {
        throw new Error('Invalid response structure');
      }
      return response.data;
    } catch (error) {
      console.error(`HTTP error ${error.response.status}: ${error.response.statusText}`);
      attempts++;
      const timeout = retryOptions.minTimeout * Math.pow(retryOptions.factor, attempts);
      await retry.sleep(timeout);
    }
  }

  throw new Error('Max retries exceeded');
}

// Example usage
fetchData()
  .then(data => {
    console.log('Products fetched successfully:', data);
  })
  .catch(error => {
    console.error('Error fetching products:', error.message);
  });
```

