const express = require('express');
const bodyParser = require('body-parser');
const crypto = require('crypto');
const mongoose = require('mongoose');

// Connect to MongoDB database
mongoose.connect('mongodb://localhost:27017/credit_card_db', { useNewUrlParser: true, useUnifiedTopology: true });

// Define the credit card schema
const CreditCardSchema = new mongoose.Schema({
  number: String,
  expiry: String,
  cvv: String
});

const CreditCard = mongoose.model('CreditCard', CreditCardSchema);

// Express app setup
const app = express();
app.use(bodyParser.json());

// Rate limiting middleware
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5 // limit each IP to 5 requests per windowMs
});

// Encrypt data in transit and at rest
const encrypt = (data) => {
  return crypto.createHash('sha256').update(data).digest('hex');
};

// Secure API endpoint for processing credit card data
app.post('/process', limiter, async (req, res) => {
  try {
    // Validate input fields using strict schema
    const { number, expiry, cvv } = req.body;
    if (!number || !expiry || !cvv) {
      throw new Error('All fields are required');
    }

    // Encrypt data in transit and at rest
    const encryptedNumber = encrypt(number);
    const encryptedExpiry = encrypt(expiry);
    const encryptedCvv = encrypt(cvv);

    // Store credit card details securely
    await CreditCard.create({
      number: encryptedNumber,
      expiry: encryptedExpiry,
      cvv: encryptedCvv
    });

    res.status(201).send('Credit card data processed successfully');
  } catch (error) {
    console.error(error);
    res.status(400).send({ message: error.message });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
